-- T-107: the decisions and the trust trail only grow. A decision with its policy citation, and the
-- trail of who did what to a case, are worth nothing if either can be edited afterwards. Generated by
-- appendOnly() in src/db/helpers/appendOnly.ts: UPDATE and DELETE raise KT001 for everyone including
-- the owner, and komtru_app holds INSERT and SELECT only.
CREATE TRIGGER komtru_append_only BEFORE UPDATE OR DELETE ON "cases"."case_decisions" FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
--> statement-breakpoint
REVOKE ALL ON "cases"."case_decisions" FROM komtru_app;
--> statement-breakpoint
GRANT INSERT, SELECT ON "cases"."case_decisions" TO komtru_app;
--> statement-breakpoint
